package com.pokedaisy.app

/**
 * SETTINGS > ASPECT > WIDE: the overworld drawn past the GBA's 240 px, so the game fills a wide
 * screen with its own pixels square. The strips beside the real frame are rebuilt every frame
 * from the game's memory (map grid, tilesets, VRAM, sprites) by the native pk_wide.c, which
 * checks each frame against what the game actually drew and fades the strips out wherever it
 * can't (battles, menu screens, transitions). The middle is always the game's own frame.
 *
 * Its tables are per release, by ROM CRC32 (pk_wide_games.h, generated by scripts/gen_wide_tables.py): retail
 * FireRed / LeafGreen / Emerald / Ruby / Sapphire in every language and revision, and the hacks it lists (Unbound,
 * Radical Red, Lazarus, SoulGold). Game Boy games are pk_wide_gb.c's (Pokémon Yellow, English, Crystal, the Legacy hacks of both, Crystal Clear and Polished Crystal 3.2.3): its own
 * rebuild of the Gen 1 / Gen 2 overworld around the 160x144 screen, by the same CRC lookup.
 */
object WideScreen {
    /** No game: WIDE off. */
    const val OFF = 0

    /** A DS game's EXPAND (nds/pk_nds_wide.cpp: its overworld's 3D past the screen's edges), for a cart the DS field
     * read knows ([ndsKnows]). */
    const val NDS = -1

    /** The carts nds/pk_nds_field.cpp has a table for (keep in step with pk_nds_field_game): by header game code
     * and revision. */
    fun ndsKnows(code: String, revision: Int): Boolean =
        code == "CPUE" && revision == 1 ||
            code in setOf("CPUF", "IPKE", "IPKD", "IPKF", "IPGE", "IPGD", "IPGF", "IRBO", "IRBF", "IRAO", "IRAF", "IREO", "IRDO") && revision == 0 ||
            com.pokedaisy.app.companion.data.DsPorts.of(code, revision) != null

    /** What to hand [MgbaCore.pkWideConfigure] for the ROM with this CRC32 ([SaveStates.crc32]'s hex form):
     * the CRC itself if pk_wide.c knows it, else [OFF]. */
    fun gameFor(crc: String): Int {
        val v = crc.toLongOrNull(16)?.toInt() ?: return OFF
        return if (v != OFF && runCatching { MgbaCore.pkWideKnows(v) }.getOrDefault(false)) v else OFF
    }

    /**
     * The CRC32 to look [rom] up by in WIDE's and the field reads' tables: its own ([crc]), or, for retail FireRed /
     * Emerald randomized by Universal Pokémon Randomizer ZX ([RandomizedRetail]), retail's - the randomizer leaves
     * the code, RAM, maps and sprites those tables describe alone. Blocking (hashes the ROM when it's unknown).
     */
    fun tablesCrc(rom: java.io.File, crc: String): String {
        val v = crc.toLongOrNull(16)?.toInt() ?: return crc
        if (runCatching { MgbaCore.pkWideKnows(v) || MgbaCore.pkFieldKnows(v) }.getOrDefault(false)) return crc
        val hit = runCatching {
            com.pokedaisy.app.companion.data.RandomizedRetail.matchStream(
                RomIdentity.gameCode(rom), RomIdentity.revision(rom), RomArchive.romSize(rom),
            ) { RomArchive.open(rom) }
        }.getOrNull()
        if (hit != null) return "%08x".format(hit.retailCrc)
        retailEngineRow(rom, v)   // the ROM's own CRC either way: known by it now, or not at all
        return crc
    }

    /**
     * A FireRed / Emerald hack edited in place that nothing knows by its CRC: when [RetailEngine] proves it kept retail's
     * engine, its own row (retail's, with the tables it moved) goes to pk_wide.c under the ROM's CRC, so WIDE and the field
     * reads know it. Whether that happened. Blocking, but light: a few hundred small reads of [rom] (the file played,
     * an archive already unpacked).
     */
    private fun retailEngineRow(rom: java.io.File, crc: Int): Boolean {
        if (!rom.isFile || rom.length() > 0x2000000L) return false
        val proof = runCatching {
            java.io.RandomAccessFile(rom, "r").use { raf ->
                val head = ByteArray(0xC0).also { raf.readFully(it) }
                val code = String(head, 0xAC, 4, Charsets.ISO_8859_1)
                if (code != "BPRE" && code != "BPEE") return false
                com.pokedaisy.app.companion.data.RetailEngine.check(code, head[0xBC].toInt() and 0xFF) { off, len ->
                    if (off < 0 || off >= raf.length()) null
                    else ByteArray(minOf(len.toLong(), raf.length() - off).toInt()).also { raf.seek(off.toLong()); raf.readFully(it) }
                }
            }
        }.getOrNull() ?: return false
        val row = proof.wideRow
        if (!proof.ramProven || row == null) {
            android.util.Log.i("pokedaisy", "retail engine: ${proof.build.id} not proven for %08x: ${proof.why.take(4)}".format(crc))
            return false
        }
        val ok = runCatching { MgbaCore.pkWideAddDerived(crc, proof.build.retailCrc, row) }.getOrDefault(false)
        android.util.Log.i("pokedaisy", "retail engine: %08x keeps ${proof.build.id}'s engine, EXPAND row ${if (ok) "set" else "refused"}".format(crc))
        return ok
    }

    /** The same for the field reads behind SCENE SPEEDS' TEXT, AUTO-RUN, RUN INDOORS and WILD ENCOUNTERS
     * ([MgbaCore.pkFieldConfigure]): WIDE's games with the field's addresses, plus the hacks WIDE doesn't draw yet. */
    fun fieldGameFor(crc: String): Int {
        val v = crc.toLongOrNull(16)?.toInt() ?: return OFF
        return if (v != OFF && runCatching { MgbaCore.pkFieldKnows(v) }.getOrDefault(false)) v else OFF
    }
}
